<?php declare(strict_types=1);
require __DIR__.'/einvoice-fields.php';
use Kulturhus\Verein\EInvoiceFields;
$line='<cac:InvoiceLine><cbc:ID>1</cbc:ID><cbc:InvoicedQuantity unitCode="C62">4</cbc:InvoicedQuantity><cbc:LineExtensionAmount>100.00</cbc:LineExtensionAmount><cac:Item><cbc:Name>Test equipment</cbc:Name><cac:ClassifiedTaxCategory><cbc:ID>S</cbc:ID><cbc:Percent>19</cbc:Percent></cac:ClassifiedTaxCategory></cac:Item><cac:Price><cbc:PriceAmount>25.00</cbc:PriceAmount><cbc:BaseQuantity>1</cbc:BaseQuantity></cac:Price></cac:InvoiceLine>';
$withLines=str_replace('</Invoice>',$line.'</Invoice>',$sample);$detail=EInvoiceFields::details($withLines);$item=$detail['items'][1];
check($item['quantity']==='4'&&$item['unit']==='C62'&&$item['unit_price']==='25.00','quantity/unit/exact price extracted');check($item['net_amount']==='100.00'&&$item['tax_rate']==='19'&&$item['tax_category']==='S','net/VAT category remain original strings');check($item['price_base_quantity']==='1'&&!$item['ambiguous'],'price base represented separately');
$credit=str_replace(['Invoice-2','<Invoice ','</Invoice>','InvoiceLine','InvoicedQuantity'],['CreditNote-2','<CreditNote ','</CreditNote>','CreditNoteLine','CreditedQuantity'],$withLines);check(EInvoiceFields::details($credit)['items'][1]['quantity']==='4','CreditNote quantities supported');
$dup=str_replace('<cbc:Percent>19</cbc:Percent>','<cbc:Percent>19</cbc:Percent><cbc:Percent>7</cbc:Percent>',$withLines);check(EInvoiceFields::details($dup)['items'][1]['ambiguous'],'duplicate VAT cannot silently overwrite first value');
$spoof=str_replace('xmlns:cbc="urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2"','xmlns:cbc="urn:untrusted"',$withLines);check(EInvoiceFields::details($spoof)['items'][1]['net_amount']==='','foreign namespace fields ignored');
$many=str_replace('</Invoice>',str_repeat($line,201).'</Invoice>',$sample);$manyResult=EInvoiceFields::details($many);check(count($manyResult['items'])===200&&$manyResult['items_truncated'],'position count capped with explicit marker');
$ciiline='<rsm:SupplyChainTradeTransaction><ram:IncludedSupplyChainTradeLineItem><ram:AssociatedDocumentLineDocument><ram:LineID>2</ram:LineID></ram:AssociatedDocumentLineDocument><ram:SpecifiedTradeProduct><ram:Name>CII equipment</ram:Name></ram:SpecifiedTradeProduct><ram:SpecifiedLineTradeDelivery><ram:BilledQuantity unitCode="C62">3</ram:BilledQuantity></ram:SpecifiedLineTradeDelivery><ram:SpecifiedLineTradeAgreement><ram:NetPriceProductTradePrice><ram:ChargeAmount>10.00</ram:ChargeAmount></ram:NetPriceProductTradePrice></ram:SpecifiedLineTradeAgreement><ram:SpecifiedLineTradeSettlement><ram:ApplicableTradeTax><ram:RateApplicablePercent>7</ram:RateApplicablePercent></ram:ApplicableTradeTax><ram:SpecifiedTradeSettlementLineMonetarySummation><ram:LineTotalAmount>30.00</ram:LineTotalAmount></ram:SpecifiedTradeSettlementLineMonetarySummation></ram:SpecifiedLineTradeSettlement></ram:IncludedSupplyChainTradeLineItem></rsm:SupplyChainTradeTransaction>';
$ciiResult=EInvoiceFields::details(str_replace('</rsm:CrossIndustryInvoice>',$ciiline.'</rsm:CrossIndustryInvoice>',$cii));check($ciiResult['items'][0]['net_amount']==='30.00'&&$ciiResult['items'][0]['quantity']==='3','CII position paths read accurately');echo "$checks combined XML position checks passed\n";
